// builds edits_A.json (idle_a, idle_b, idle_c, perch_a, perch_b); old lines are parsed from packet_A.md
// node gen_A.js [samples]   - writes the edits, runs the checks, prints sample chains
const fs = require('fs'), path = require('path');
const dir = __dirname;
const pk = fs.readFileSync(path.join(dir, 'packet_A.md'), 'utf8').split(/\r?\n/);
const old = {}; let cur = null;
for (const l of pk) {
  const h = /^### ([HM]) @(\S+)/.exec(l); if (h) { cur = h[1] + ':' + h[2]; old[cur] = []; continue; }
  if (cur && /^\d+ \| /.test(l)) { const parts = l.split(' | '); old[cur].push(parts[1].trim()); }
  else if (l.startsWith('#')) cur = null;
}
