// ---------- edits ----------
const out = [];
for (const key of Object.keys(N)) {
  const [who, list] = key.split(':'); const o = old[key]; if (!o) throw new Error('no old list ' + key);
  const nw = N[key];
  nw.forEach(([mk, uk, en], i) => {
    const u = mk + ' ' + uk, e = mk + ' ' + en;
    if (i < o.length) out.push({ who, list, op: 'set', old: o[i], uk: u, en: e });
    else out.push({ who, list, op: 'add', uk: u, en: e });
  });
  for (let i = nw.length; i < o.length; i++) out.push({ who, list, op: 'del', old: o[i] });
}
for (const k in old) if (!N[k]) console.log('UNTOUCHED old list', k);
fs.writeFileSync(path.join(dir, 'edits_A.json'), JSON.stringify(out, null, 1));

// ---------- checks ----------
let bad = 0; const warn = (...a) => { bad++; console.log(...a); };
const tiersOf = mk => { const m = /^~(\d+) /.exec(mk); return m ? m[1].split('').map(Number) : [1, 2, 3]; };
const thr = mk => mk.replace(/^~\d+ /, '').slice(1);
const ans = mk => thr(mk).split('>')[0].split('|');
const nxt = mk => { const t = thr(mk); return t.includes('>') ? t.slice(t.indexOf('>') + 1) : null; };
const SC = {
  idle_a: [['M', 'м_почин'], ['H', 'х_відповідь'], ['M', 'м_кінець']],
  idle_b: [['H', 'х_почин'], ['M', 'м_відповідь'], ['H', 'х_кінець'], ['M', 'м_кінець']],
  idle_c: [['M', 'м_про_гравця'], ['H', 'х_про_гравця'], ['M', 'м_кінець']],
  perch_a: [['H', 'хп_розмова'], ['M', 'мп_відповідь'], ['H', 'х_кінець']],
  perch_b: [['M', 'мп_розмова'], ['H', 'хп_відповідь'], ['M', 'м_кінець']],
};
const linesOf = (sc, who, list) => N[who + ':' + list].filter(x => thr(x[0]).startsWith(sc + '.'));
const reached = new Set();
for (const sc in SC) {
  const steps = SC[sc];
  for (const tH of [1, 2, 3]) for (const tM of [1, 2, 3]) {
    const seen = new Set();
    (function walk(i, thread) {
      if (i >= steps.length) return; const key = i + '|' + thread; if (seen.has(key)) return; seen.add(key);
      const [who, list] = steps[i], t = who === 'H' ? tH : tM;
      const ls = linesOf(sc, who, list).filter(x => tiersOf(x[0]).includes(t) && (thread == null || ans(x[0]).includes(thread) || ans(x[0]).includes(sc)));
      if (thread != null && ls.length < 2) warn('short', sc, 'step', i, who + ':' + list, 'thread', thread, 'tier', t, 'n', ls.length);
      for (const x of ls) { reached.add(who + ':' + list + ':' + x[1]); walk(i + 1, nxt(x[0]) || (thread == null ? ans(x[0])[0] : thread)); }
      if (i === steps.length - 1) for (const x of ls) if (nxt(x[0])) warn('chain on last step', sc, x[0], x[1]);
    })(0, null);
  }
  for (const [who, list] of steps) for (const x of linesOf(sc, who, list)) if (!reached.has(who + ':' + list + ':' + x[1])) warn('unreached', sc, who + ':' + list, x[0], x[1]);
}
// every line carries one of our prefixes; texts unique in a list
for (const k in N) { const s = new Set(); for (const x of N[k]) { if (!/^(~\d+ )?\^(idle_a|idle_b|idle_c|perch_a|perch_b)\./.test(x[0])) warn('prefix', k, x[0]); if (s.has(x[1])) warn('dup', k, x[1]); s.add(x[1]); } }
// swears (Patterns.SwearRoots); {м_слівце} counts as one
const ROOTS = [['курв'], ['бля'], ['сук'], ['хуй', 'хуя', 'хує', 'хуї'], ['пізд', 'пизд'], ['йоб', 'йоп'], ['гівн'], ['срак', 'срав', 'сран'], ['мудак', 'мудил', 'довбойоб'], ['трясц'], ['ядри'], ['хер', 'хрін'], ['мать '], ['дуп']];
function swears(s) { const l = s.toLowerCase(); let tot = 0, rep = false; for (const f of ROOTS) { let n = 0; for (const r of f) { let i = l.indexOf(r); while (i >= 0) { n++; i = l.indexOf(r, i + r.length); } } if (n >= 2) rep = true; tot += n; } tot += (s.match(/\{м_слівце\}/g) || []).length; return [tot, rep]; }
for (const k in N) for (const x of N[k]) { const [n, rep] = swears(x[1]); if (k.startsWith('H:') && n) warn('hugin swears', x[1]); if (k.startsWith('M:') && (n > 1 || rep)) warn('munin swears', n, x[1]); }
// gender splits inside a word: the two forms must differ from their first letter
for (const k in N) for (const x of N[k]) for (const m of x[1].matchAll(/(\S?)\{([^{}|>]*)\|([^{}|]*)\}/g)) { if (m[1] && /[а-яіїєґ']/i.test(m[1]) && m[2] && m[3] && m[2][0] === m[3][0]) warn('split', x[1]); }
console.log('ops', out.length, 'set', out.filter(x => x.op === 'set').length, 'add', out.filter(x => x.op === 'add').length, 'del', out.filter(x => x.op === 'del').length, 'problems', bad);
const cnt = {}; for (const e of out) { const k = e.who + ':' + e.list; cnt[k] = cnt[k] || { set: 0, add: 0, del: 0 }; cnt[k][e.op]++; } console.log(cnt);

// ---------- sample chains ----------
const nS = +process.argv[2] || 0;
const pick = a => a[Math.floor(Math.random() * a.length)];
for (const sc in SC) for (let s = 0; s < nS; s++) {
  const tH = 1 + Math.floor(Math.random() * 3), tM = 1 + Math.floor(Math.random() * 3); let thread = null; const lines = [];
  for (const [who, list] of SC[sc]) { const t = who === 'H' ? tH : tM; const ls = linesOf(sc, who, list).filter(x => tiersOf(x[0]).includes(t) && (thread == null || ans(x[0]).includes(thread))); if (!ls.length) break; const x = pick(ls); thread = nxt(x[0]) || (thread == null ? ans(x[0])[0] : thread); lines.push((who === 'H' ? 'Хугін: ' : 'Мунін: ') + x[1]); }
  console.log(`[${sc}] Х${tH} М${tM}\n  ` + lines.join('\n  '));
}
